import fs from 'node:fs';import{createClient}from'@supabase/supabase-js';process.loadEnvFile('.env');process.loadEnvFile('.env.backup.local');const db=createClient(process.env.VITE_SUPABASE_URL,process.env.SUPABASE_SERVICE_ROLE_KEY,{auth:{persistSession:false}});async function read(q){const r=await q;if(r.error)throw r.error;return r.data;}
const mats=await read(db.from('panol_materiales').select('*').or('descripcion.ilike.%compos%,descripcion.ilike.%ruido%,descripcion.ilike.%acústic%,descripcion.ilike.%acustic%,alias.ilike.%compos%,alias.ilike.%ruido%').order('id'));fs.writeFileSync('backups/placas-antiruido-20261103/materiales.json',JSON.stringify(mats,null,2));console.log(JSON.stringify(mats.map(x=>({id:x.id,descripcion:x.descripcion,codigo:x.codigo,activo:x.activo,es_requisito:x.es_requisito,alias:x.alias,unidad:x.unidad_medida}))));
const ids=mats.map(x=>x.id);const snap=await read(db.from('panol_obra_materiales_snapshot').select('*').or('material_id.in.('+ids.join(',')+'),descripcion.ilike.%compos%,descripcion.ilike.%ruido%').order('id'));fs.writeFileSync('backups/placas-antiruido-20261103/snapshots.json',JSON.stringify(snap,null,2));console.log(JSON.stringify({snapshots:snap.map(x=>({id:x.id,material:x.material_id,req:x.requisito_material_id,descripcion:x.descripcion,obra:x.obra_id,cantidad:x.cantidad,egresado:x.cantidad_egresada,estado:x.estado,source:x.source,sede:x.stock_sede}))}));
console.log(JSON.stringify({links:await read(db.from('panol_requisito_productos').select('*').or('requisito_material_id.in.('+ids.join(',')+'),producto_material_id.in.('+ids.join(',')+')'))}));
